UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Generated text is inserted into commands, queries, HTML, policies or tool arguments without contextual validation.","customer_symptom":"A user or operator may observe generated text is inserted into commands, queries, html, policies or tool arguments without contextual validation; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in generated text is inserted into commands, queries, html, policies or tool arguments without contextual validation, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents whose output drives systems"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents whose output drives systems and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If generated text is inserted into commands, queries, html, policies or tool arguments without contextual validation, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-081 output parser, downstream sink, tool interface or policy-consumer change","ARL-KB-081 new command, query, markup or executable output destination","ARL-KB-081 output-injection or unintended downstream-execution evidence","ARL-KB-081 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='1caca0c7af0c2b1c5005f59750ad6b9ce2dede6dbffd99c56193be22ccbd9bff', updated_at='2026-08-06' WHERE id='ARL-KB-081';
UPDATE risk_knowledge_checks SET objective='Determine whether model-generated output is treated as untrusted data and independently validated before reaching commands, queries, markup, policies, tool parameters or other consequential downstream interpreters.', method='Trace each model-output path to its downstream sink and identify the parser, interpreter or business rule applied there. Using owner-authorised synthetic inputs, test payloads specific to each sink and verify parameterisation, contextual encoding, typed validation and independent policy checks prevent generated text from acquiring unintended execution semantics.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-081 assessed system, version, environment and scope for Model output is trusted as safe code or data","ARL-KB-081 control configuration or source location showing how reduce the likelihood and impact of model output is trusted as safe code or data and make the remaining risk visible.","ARL-KB-081 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-081 policy, authorization, tool or audit events proving whether the tested model output is trusted as safe code or data path executed","ARL-KB-081 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-081 passes only when “Model output is trusted as safe code or data” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-081 fails when generated text is inserted into commands, queries, html, policies or tool arguments without contextual validation, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-081 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='359c8da1dd16c5d7eb15a893f33715f97e8727441a7438f27fd772d57a5f4f41', updated_at='2026-08-06' WHERE entry_id='ARL-KB-081';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of model output is trusted as safe code or data and make the remaining risk visible.', recommended_remediation='Treat output as untrusted, use typed schemas, contextual encoding, parameterised APIs and independent policy validation.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-081: Treat model output as untrusted input at every downstream trust boundary.","ARL-KB-081: Prefer typed schemas and parameterised APIs over generated executable syntax.","ARL-KB-081: Apply sink-specific validation, encoding and independent authorization before consequential use."]', monitoring='For ARL-KB-081, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-081 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-081: “Model output is trusted as safe code or data” is no longer reproducible against the exact remediated version.","ARL-KB-081: Authorised in-scope use completes successfully, remains within the documented asset scope for model output is trusted as safe code or data, and produces no unintended side effect.","ARL-KB-081: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-081: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d549dad305485dd588569ea5cf0dd91603cd9f400956312f9ed293167e56d7b7', updated_at='2026-08-06' WHERE entry_id='ARL-KB-081';
