UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Newlines and control characters alter headers, forge audit events or split downstream messages.","customer_symptom":"A user or operator may observe newlines and control characters alter headers, forge audit events or split downstream messages; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in newlines and control characters alter headers, forge audit events or split downstream messages, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents creating messages or logs"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents creating messages or logs and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If newlines and control characters alter headers, forge audit events or split downstream messages, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-084 email, logging, protocol encoder or message-format change","ARL-KB-084 new generated header, message or structured-log field","ARL-KB-084 CRLF, log-forging or protocol-splitting evidence","ARL-KB-084 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='2201092f51c24c8cca59a8a4f7b2722a30bdc48aa4bb9489573d67bae6bc4b2f', updated_at='2026-08-06' WHERE id='ARL-KB-084';
