UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Reports, spreadsheets, archives or documents include formulas, macros, links or embedded payloads.","customer_symptom":"A user or operator may observe reports, spreadsheets, archives or documents include formulas, macros, links or embedded payloads; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in reports, spreadsheets, archives or documents include formulas, macros, links or embedded payloads, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["file-generating agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between file-generating agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If reports, spreadsheets, archives or documents include formulas, macros, links or embedded payloads, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last