UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A pre-deployment assessment becomes stale while live requests and tool calls execute without policy checks.","customer_symptom":"A user or operator may observe a pre-deployment assessment becomes stale while live requests and tool calls execute without policy checks; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in a pre-deployment assessment becomes stale while live requests and tool calls execute without policy checks, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["production tool-using agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between production tool-using agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a pre-deployment assessment becomes stale while live requests and tool calls execute without policy checks, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json=