vant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-089 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='3e52fe248133faa83db6b1d55084cfc66a89f78b3d98d717cd677c7a4d5d79b3', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of logs and traces contain secrets or personal data and make the remaining risk visible.', recommended_remediation='Redact at source, use structured allowlists, separate security evidence from raw content, limit access and apply retention.', default_owner='Observability and privacy owner', priority='P1', implementation_principles_json='["ARL-KB-089: Minimise observability content and redact sensitive fields at the earliest practical boundary.","ARL-KB-089: Prefer structured allowlists of evidence fields over logging raw prompts, payloads or tool results.","ARL-KB-089: Restrict access and retention for logs, traces and support exports according to data sensitivity."]', monitoring='For ARL-KB-089, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Observability and privacy owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-089 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-089: “Logs and traces contain secrets or personal data” is no longer reproducible against the exact remediated version.","ARL-KB-089: Authorised in-scope use completes successfully, remains within the documented asset scope for logs and traces contain secrets or personal data, and produces no unintended side effect.","ARL-KB-089: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-089: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='fb8c83cf008cd5f09e8bf63ef13bfbd1654d7acc2dd6b62d27f9713c82c2882c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='ac4e6747c0d1957d4716f68ea472a34c2972f3108db31ba5bfb54406b5769421', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-089','high','active','2026-10-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The organisation cannot prove who requested, approved, changed and executed a consequential action.","customer_symptom":"A user or operator may observe the organisation cannot prove who requested, approved, changed and executed a consequential action; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in the organisation cannot prove who requested, approved, changed and executed a consequential action, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["consequential agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between consequential agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the organisation cannot prove who requested, approved, changed and executed a consequential action, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-090 audit schema, correlation identifier, evidence store or retention change","ARL-KB-090 new consequential action, approval workflow or execution path","ARL-KB-090 missing, inconsistent or tampered decision-chain evidence","ARL-KB-090 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='47a1453156aa0b246b8f55b567854ad07d36483f20141c55fbeb50cf9b0a7fdc', updated_at='2026-08-06' WHERE id='ARL-KB-090';
UPDATE risk_knowledge_checks SET objective='Determine whether evidence is sufficient to reconstruct who requested, approved, changed and executed a consequential action against the exact system, policy and tool versions involved.', method='Select representative consequential actions and reconstruct the full decision chain from retained evidence: requester identity and intent, canonical parameters, policy decision and version, model and tool versions, approval identity and scope, execution result and correlated timestamps. Verify the reconstruction is attributable and internally consistent.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-090 assessed system, version, environment and scope for Audit coverage cannot reconstruct a decision","ARL-KB-090 control configuration or source location showing how reduce the likelihood and impact of audit coverage cannot reconstruct a decision and make the remaining risk visible.","ARL-KB-090 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-090 policy, authorization, tool or audit events proving whether the tested audit coverage cannot reconstruct a decision path executed","ARL-KB-090 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-090 passes only when “Audit coverage cannot reconstruct a decision” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-090 fails when the organisation cannot prove who requested, approved, changed and executed a consequential action, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-090 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='55eb7db2f7005faa09488005250bbd347fd62e262d9e28f6bf07365bc48f8ce3', updated_at='2026-08-06' WHERE entry_id='ARL-KB-090';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of audit coverage cannot reconstruct a decision and make the remaining risk visible.', recommended_remediation='Record correlated, tamper-evident events with verified identities, canonical parameters, policy/version digests and outcome.', default_owner='Assurance owner', priority='P1', implementation_principles_json='["ARL-KB-090: Correlate request, policy, approval and execution evidence using stable transaction identifiers.","ARL-KB-090: Record verified identities, canonical material parameters and exact policy, model and tool versions.","ARL-KB-090: Protect consequential audit evidence from silent tampering while preserving privacy and proportional retention."]', monitoring='For ARL-KB-090, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Assurance owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-090 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-090: “Audit coverage cannot reconstruct a decision” is no longer reproducible against the exact remediated version.","ARL-KB-090: Authorised in-scope use completes successfully, remains within the documented asset scope for audit coverage cannot reconstruct a decision, and produces no unintended side effect.","ARL-KB-090: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-090: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='f09a26d590e0f3fea5489f336eded25187b0b0ee85d2bb5f71ed73588254f79e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-090';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='0a95a65df30becfd338434ba35eef77fa24e237fedcbf824ec9563e72a975e48', updated_at='2026-08-06' WHERE entry_id='ARL-KB-090';
